from manim import *


class ActionsVectorScene(VectorScene):
    def construct(self):
        self.add_plane()

        # Objects
        circle = Circle(radius=1)
        circle.set_stroke(RED)
        circle.set_fill(RED)
        circle.move_to([2, 1, 0])
        vector = Vector(direction=2 * RIGHT + UP)
        vector.set_color(WHITE)
        vector.move_to([0, 0, 0])
        eq = MathTex(r"e^{i\pi} + 1 = 0", font_size=48)
        eq.set_color(WHITE)
        eq.move_to([-3, 2, 0])

